+            Arguments.of(
+                operation,
+                async,
+                400,
+                "{\"error\":\"unknown shape\"}",
+                BadRequestException.class.getName()));
+      }
+    }
+    return arguments.stream();
+  }
+
+  private static String error(String code) {
